#include "Core.hpp"
#include <future>
#include <iostream>
namespace udm {struct CatalogCheckpointTestAccess {static void observe(Manager& m,std::function<void(const char*)> f){Lock lock(m.mutex);m.catalogCheckpoint=std::move(f);}};}
using namespace udm;
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json cases=Json::array();std::string error;try{
 for(const std::string kind:{"ordinary","replacement","original-scope"}){const auto folder=root/wide(kind);Manager m(folder/L"catalog");const auto files=folder/L"files";fs::create_directories(files);auto prefs=m.state["Settings"];prefs["DownloadFolder"]=utf8(files.wstring());prefs["CategoryFolders"]=false;m.setSettings(prefs);JobPtr original;std::string oldHash;if(kind!="ordinary"){original=m.add("https://fixture.example/old","","result.bin","Main queue",true);atomicText(original->target(),"old bytes",false);oldHash=fileHash(original->target());original->data["Status"]="Complete";original->data["Size"]=9;original->data["Received"]=9;original->data["Sha256"]=oldHash;original->data["Finished"]=date();}
 auto j=m.add("https://fixture.example/new","",original?"next.bin":"result.bin","Main queue",true);if(original){j->data["FileName"]="result.bin";j->data["ReplacementOf"]=original->id();j->data["ReplacementHash"]=oldHash;j->data["PreviousPath"]=utf8((files/L"previous.bin").wstring());}m.save();const auto stage=files/L"stage.part";atomicText(stage,"verified bytes",false);const auto hash=fileHash(stage);CatalogCheckpointTestAccess::observe(m,[&](const char* point){if(std::string_view(point)==(original?"replacement-file-moved":"publication-file-moved"))throw std::runtime_error("Owned discovery control intent");});try{m.publishFile(j,stage,hash);}catch(...){}CatalogCheckpointTestAccess::observe(m,{});
 std::promise<void> entered,release;auto ready=entered.get_future();auto wait=release.get_future().share();std::atomic_bool first=false;CatalogCheckpointTestAccess::observe(m,[&](const char* point){if(std::string_view(point)=="recovery-journal-snapshot-read"&&!first.exchange(true)){entered.set_value();if(wait.wait_for(std::chrono::seconds(10))!=std::future_status::ready)throw std::runtime_error("Discovery control deadline");}});auto task=std::async(std::launch::async,[&]{m.recoverReplacements(kind=="original-scope"?original:j);});struct Unblock {std::promise<void>& p;~Unblock(){try{p.set_value();}catch(...){}}}unblock{release};if(ready.wait_for(std::chrono::seconds(5))!=std::future_status::ready)throw std::runtime_error("No held journal read");bool available;{std::unique_lock<std::recursive_mutex> lock(m.mutex,std::try_to_lock);available=lock.owns_lock();}release.set_value();task.get();CatalogCheckpointTestAccess::observe(m,{});const bool exact=str(j->data,"Status")=="Complete"&&fileHash(j->target())==hash;cases.push_back({{"kind",kind},{"actualHeldJournalRead",true},{"modelAvailable",available},{"exactCompleteBytes",exact}});if(available||!exact)throw std::runtime_error("Unexpected 8.50 discovery control outcome");m.stop();}
 }catch(const std::exception& e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"cases",cases}}.dump(2),false);std::cout<<cases.dump()<<"\n";return error.empty()?0:1;}
